            bsuccess = _ReorderACL(pdacl_padded);
            if (bsuccess)
                bsuccess = This->SetACL(pdacl_padded);
        }
        else
            PyWin_SetAPIError(funcname);
    }

    if (pdacl_padded)
        free(pdacl_padded);
    if (bsuccess) {
        Py_INCREF(Py_None);
        return Py_None;
    }
    return NULL;
}

