		  htons (((p0 & 0xff) << 8) | (p1 & 0xff));
	      if (data_addr_sa4->sin_addr.s_addr
		  != ((struct sockaddr_in *) &hisctladdr)->sin_addr.s_addr)
		{
		  printf ("Passive mode address mismatch.\n");
		  (void) command ("ABOR");	/* Cancel any open connection.  */
		  goto bad;
		}
	    } /* PASV */
